local HardyShankMaker = {}
local PRODUCTS = {
    iron_hardyshank = { name = "Železni drg za trde nastavke", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni drg za trde nastavke za kovace." },
    bronze_hardyshank = { name = "Bronast drg za trde nastavke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast drg za trde nastavke za kovace." },
    silver_hardyshank = { name = "Srebrn drg za trde nastavke", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn drg za trde nastavke za kovace." },
    gilded_hardyshank = { name = "Pozlačen drg za trde nastavke", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen drg za trde nastavke za kovace." },
    jewel_set_hardyshank = { name = "Draguljast drg za trde nastavke", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast drg za trde nastavke za kovace." },
    royal_sovereign_hardyshank = { name = "Kraljevski suveren drg za trde nastavke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren drg za trde nastavke z biseri za krono." },
}
local BUILDINGS = {
    hardyshank_workshop = { name = "Hardyshank delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hardyshank_house = { name = "Hardyshank hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hardyshank_atelier = { name = "Mojstrski hardyshank atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hardyshank_palace = { name = "Suverena hardyshank palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HardyShankMaker.ironStock=18; HardyShankMaker.bronzeStock=14; HardyShankMaker.woodStock=10; HardyShankMaker.leatherStock=8; HardyShankMaker.silverStock=8; HardyShankMaker.goldStock=6; HardyShankMaker.jewelStock=4; HardyShankMaker.pearlStock=4
HardyShankMaker.productStock = {}; HardyShankMaker.buildings = {}; HardyShankMaker.maker = nil; HardyShankMaker.activeMaking = {}; HardyShankMaker.totalProducts = 0; HardyShankMaker.dayTimer = 0
function HardyShankMaker.init() HardyShankMaker.ironStock=18; HardyShankMaker.bronzeStock=14; HardyShankMaker.woodStock=10; HardyShankMaker.leatherStock=8; HardyShankMaker.silverStock=8; HardyShankMaker.goldStock=6; HardyShankMaker.jewelStock=4; HardyShankMaker.pearlStock=4; HardyShankMaker.productStock={}; HardyShankMaker.buildings={}; HardyShankMaker.maker=nil; HardyShankMaker.activeMaking={}; HardyShankMaker.totalProducts=0; HardyShankMaker.dayTimer=0; print("[HardyShankMaker] Royal Hardy Shank Maker System initialized (6 products, 4 buildings)") end
function HardyShankMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HardyShankMaker.maker={name=n or ("Drgnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Drgnik najet: %s (spretnost: %d)",HardyShankMaker.maker.name,s),"success") end; return true end
function HardyShankMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HardyShankMaker.build(id) local ok,e=HardyShankMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HardyShankMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HardyShankMaker.getQualityBonus() local b=0; for _,bd in ipairs(HardyShankMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HardyShankMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HardyShankMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HardyShankMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HardyShankMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HardyShankMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HardyShankMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HardyShankMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HardyShankMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HardyShankMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HardyShankMaker.buildings==0 then return false,"Potrebna drgna delavnica" end; if not HardyShankMaker.maker then return false,"Potreben drgnik" end; return true end
function HardyShankMaker.make(pt,qty) qty=qty or 1; local ok,e=HardyShankMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HardyShankMaker.ironStock=HardyShankMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HardyShankMaker.bronzeStock=HardyShankMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HardyShankMaker.woodStock=HardyShankMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HardyShankMaker.leatherStock=HardyShankMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HardyShankMaker.silverStock=HardyShankMaker.silverStock-d.silverCost*qty end; if d.goldCost then HardyShankMaker.goldStock=HardyShankMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HardyShankMaker.jewelStock=HardyShankMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HardyShankMaker.pearlStock=HardyShankMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HardyShankMaker.maker then t=math.max(1,t-math.floor(HardyShankMaker.maker.skill/13)) end; table.insert(HardyShankMaker.activeMaking,{id="hardyshank_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HardyShankMaker.completeMaking(m) local q=1.0+(HardyShankMaker.getQualityBonus()/100); if HardyShankMaker.maker then q=q+(HardyShankMaker.maker.skill/140) end; q=math.min(2.5,q); HardyShankMaker.productStock[m.productType]=(HardyShankMaker.productStock[m.productType] or 0)+m.quantity; HardyShankMaker.totalProducts=HardyShankMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HardyShankMaker.maker then HardyShankMaker.maker.itemsMade=HardyShankMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HardyShankMaker.maker.skill=math.min(100,HardyShankMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Drg izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hardyshank.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HardyShankMaker.update(dt) if not _G.state then return end; HardyShankMaker.dayTimer=HardyShankMaker.dayTimer+dt; if HardyShankMaker.dayTimer>=30 then HardyShankMaker.dayTimer=0; for i=#HardyShankMaker.activeMaking,1,-1 do local m=HardyShankMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HardyShankMaker.completeMaking(m); table.remove(HardyShankMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HardyShankMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HardyShankMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HardyShankMaker.getStats() return {ironStock=HardyShankMaker.ironStock,bronzeStock=HardyShankMaker.bronzeStock,woodStock=HardyShankMaker.woodStock,leatherStock=HardyShankMaker.leatherStock,silverStock=HardyShankMaker.silverStock,goldStock=HardyShankMaker.goldStock,jewelStock=HardyShankMaker.jewelStock,pearlStock=HardyShankMaker.pearlStock,productStock=HardyShankMaker.productStock,numBuildings=#HardyShankMaker.buildings,hasMaker=HardyShankMaker.maker~=nil,makerName=HardyShankMaker.maker and HardyShankMaker.maker.name or "—",makerSkill=HardyShankMaker.maker and HardyShankMaker.maker.skill or 0,activeMaking=#HardyShankMaker.activeMaking,totalProducts=HardyShankMaker.totalProducts} end
return HardyShankMaker
